import{_ as l,a0 as p,w as o,s as r,I as e,x as a,a1 as t,A as i,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const f=JSON.parse('{"title":"在 CentOS 和 RHEL 系统上安装安全补丁或自动更新 | LCTT x X-CMD","titleTemplate":false,"description":"在 CentOS 和 RHEL 系统上安装安全补丁或自动更新 | LCTT (201612) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 CentOS 和 RHEL 系统上安装安全补丁或自动更新 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 CentOS 和 RHEL 系统上安装安全补丁或自动更新 | LCTT (201612) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201612/20161130 Install Security Patches or Updates Automatically on CentOS and RHEL","title":"在 CentOS 和 RHEL 系统上安装安全补丁或自动更新","tag":"201612","desc":""},"relativePath":"201612/20161130 Install Security Patches or Updates Automatically on CentOS and RHEL.md","filePath":"[post].md"}'),h={name:"201612/20161130 Install Security Patches or Updates Automatically on CentOS and RHEL.md"};function c(u,s,g,k,m,b){const n=p("Link");return o(),r("div",null,[s[16]||(s[16]=e("h1",{id:"在-centos-和-rhel-系统上安装安全补丁或自动更新",tabindex:"-1"},[a("在 CentOS 和 RHEL 系统上安装安全补丁或自动更新 "),e("a",{class:"header-anchor",href:"#在-centos-和-rhel-系统上安装安全补丁或自动更新","aria-label":"Permalink to “在 CentOS 和 RHEL 系统上安装安全补丁或自动更新”"},"​")],-1)),s[17]||(s[17]=e("p",null,"在 Linux 系统上，一个最重要的需求就是为相应的 Linux 版本定期安装最新的安全补丁，或者更新。",-1)),e("p",null,[s[1]||(s[1]=a("在之前的文章中，我们分享了",-1)),t(n,{href:"http://www.tecmint.com/auto-install-security-updates-on-debian-and-ubuntu/"},{default:i(()=>[...s[0]||(s[0]=[a("如何在 Debian/Ubuntu 上配置自动安全更新",-1)])]),_:1}),s[2]||(s[2]=a("，在这篇文章中，我们将分享如何在 CentOS/RHEL 7/6 版本中设置在需要时自动更新重要的安全补丁。",-1))]),s[18]||(s[18]=d(`<p>和它同一家族的其它 Linux 版本（Fedora 或 Scientific Linux）中可以用类似的方法进行配置。</p><h3 id="在-centos-rhel-系统上配置自动安全更新" tabindex="-1">在 CentOS/RHEL 系统上配置自动安全更新 <a class="header-anchor" href="#在-centos-rhel-系统上配置自动安全更新" aria-label="Permalink to “在 CentOS/RHEL 系统上配置自动安全更新”">​</a></h3><p>在 CentOS/RHEL 7/6 系统上，你需要安装下面的安装包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># yum update -y &amp;&amp; yum install yum-cron -y</span></span></code></pre></div><h3 id="在-centos-rhel-7-系统上启用自动安全更新" tabindex="-1">在 CentOS/RHEL 7　系统上启用自动安全更新 <a class="header-anchor" href="#在-centos-rhel-7-系统上启用自动安全更新" aria-label="Permalink to “在 CentOS/RHEL 7　系统上启用自动安全更新”">​</a></h3><p>安装完成以后，打开 <code>/etc/yum/yum-cron.conf</code>，然后找到下面这些行内容，你必须确保它们的值和下面展示的一样</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>update_cmd = security</span></span>
<span class="line"><span>update_messages = yes</span></span>
<span class="line"><span>download_updates = yes</span></span>
<span class="line"><span>apply_updates = yes</span></span></code></pre></div><p>第一行表明自动更新命令行应该像这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># yum --security upgrade</span></span></code></pre></div><p>而其它的行保证了能够通知并自动下载、安装安全升级。</p><p>为了使来自 root@localhost 的通知能够通过邮件发送给同一账户（再次说明，你可以选择其他账户，如果你想这样的话），下面这些行也是必须的。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>emit_via = email</span></span>
<span class="line"><span>email_from = root@localhost</span></span>
<span class="line"><span>email_to = root</span></span></code></pre></div><h3 id="在-centos-rhel-6-上启用自动安全更新" tabindex="-1">在 CentOS/RHEL 6 上启用自动安全更新 <a class="header-anchor" href="#在-centos-rhel-6-上启用自动安全更新" aria-label="Permalink to “在 CentOS/RHEL 6 上启用自动安全更新”">​</a></h3><p>默认情况下， cron 任务被配置成了立即下载并安装所有更新，但是我们可以通过在 <code>/etc/sysconfig/yum-cron</code> 配置文件中把下面两个参数改为 <code>yes</code>，从而改变这种行为。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># 不要安装，只做检查（有效值： yes|no）</span></span>
<span class="line"><span>CHECK_ONLY=yes</span></span>
<span class="line"><span># 不要安装，只做检查和下载（有效值： yes|no）</span></span>
<span class="line"><span># 要求 CHECK_ONLY=yes（先要检查后才可以知道要下载什么）</span></span>
<span class="line"><span>DOWNLOAD_ONLY=yes</span></span></code></pre></div><p>为了启用关于安装包更新的邮件通知，你需要把 <code>MAILTO</code> 参数设置为一个有效的邮件地址。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># 默认情况下 MAILTO 是没有设置的，crond 会将输出发送邮件给自己（LCTT 译注：执行 cron 的用户，这里是 root）</span></span>
<span class="line"><span># 例子： MAILTO=root</span></span>
<span class="line"><span>MAILTO=admin@tecmint.com</span></span></code></pre></div><p>最后，打开并启用 <code>yum-cron</code> 服务：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>------------- On CentOS/RHEL 7 ------------- </span></span>
<span class="line"><span>systemctl start yum-cron</span></span>
<span class="line"><span>systemctl enable yum-cron</span></span>
<span class="line"><span>------------- On CentOS/RHEL 6 -------------  </span></span>
<span class="line"><span># service yum-cron start</span></span>
<span class="line"><span># chkconfig --level 35 yum-cron on</span></span></code></pre></div><p>恭喜你，你已经成功的在 CentOS/RHEL 7/6 系统上设置了自动升级。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>在这篇文章中，我们讨论了如何保持你的服务器定期更新或升级最新的安全补丁。另外，为了保证当新的补丁被应用时你自己能够知道，你也学习了如何配置邮件通知。</p><p>如果你有任何关于这篇文章的疑问，请在下面的评论区留下你的问题。我们期待收到你的回复。</p><hr>`,24)),e("p",null,[s[4]||(s[4]=a("via: ",-1)),t(n,{href:"http://www.tecmint.com/auto-install-security-patches-updates-on-centos-rhel/"},{default:i(()=>[...s[3]||(s[3]=[a("http://www.tecmint.com/auto-install-security-patches-updates-on-centos-rhel/",-1)])]),_:1})]),e("p",null,[s[8]||(s[8]=a("作者：",-1)),t(n,{href:"http://www.tecmint.com/author/gacanepa/"},{default:i(()=>[...s[5]||(s[5]=[a("Gabriel Cánepa",-1)])]),_:1}),s[9]||(s[9]=a(" 译者：",-1)),t(n,{href:"https://github.com/ucasFL"},{default:i(()=>[...s[6]||(s[6]=[a("ucasFL",-1)])]),_:1}),s[10]||(s[10]=a(" 校对：",-1)),t(n,{href:"https://github.com/jasminepeng"},{default:i(()=>[...s[7]||(s[7]=[a("jasminepeng",-1)])]),_:1})]),e("p",null,[s[13]||(s[13]=a("本文由 ",-1)),t(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[11]||(s[11]=[a("LCTT",-1)])]),_:1}),s[14]||(s[14]=a(" 原创编译，",-1)),t(n,{href:"https://linux.cn/"},{default:i(()=>[...s[12]||(s[12]=[a("Linux中国",-1)])]),_:1}),s[15]||(s[15]=a(" 荣誉推出",-1))])])}const L=l(h,[["render",c]]);export{f as __pageData,L as default};
